"""Generate a Cellebrite (Inseyets) Physical Analyzer decoding script.

The output is an IronPython 2.7 script for the Decoding scope. Run it from
Python > Run script > Decoding Scope, or package it into a .tplug with
PluginPackager.exe (see docs/INSTALL.md).
"""
import pprint

from . import spec as specmod

HEADER = '''# -*- coding: utf-8 -*-
# Generated by Project Obscure Benelux from specs/%(id)s/parser.yaml
# Do not edit this file by hand: change parser.yaml and regenerate.
#
# App:      %(name)s (%(country)s)
# Status:   %(status)s
# Platform: Cellebrite / Inseyets Physical Analyzer, Python > Run script > Decoding Scope
from physical import *
import SQLiteParser
from System import DateTime, DateTimeKind
from System.Convert import IsDBNull

'''


def generate(spec):
    app = spec['app']
    arts = spec['artifacts']
    out = [HEADER % app]
    out.append(specmod.read_template('runtime.py'))
    out.append('\n\n')
    out.append(specmod.read_template('shaper.py'))
    out.append('\n\nOBS_APP = %s\n' % pprint.pformat(
        {'id': app['id'], 'name': app['name']}, sort_dicts=False))
    out.append('\nOBS_ARTIFACTS = %s\n' % pprint.pformat(
        [specmod.runtime_artifact(a) for a in arts], sort_dicts=False))
    regexes = dict((a['id'], spec['sources'][a['source']].get('cellebrite_regex')
                    or specmod.glob_to_regex(spec['sources'][a['source']]['path'])) for a in arts)
    out.append('\nOBS_PATH_REGEX = %s\n\n\n' % pprint.pformat(regexes, sort_dicts=False))
    out.append(specmod.read_template('cellebrite_engine.py'))
    out.append('\n\nobs_main()\n')
    return {'cellebrite/%s.py' % app['id']: ''.join(out)}
